def compute(vars):
    old_rate = vars["v1"]
    new_rate = vars["v2"]
    change = new_rate - old_rate

    return {
        "value": change,
        "trace": {
            "old_rate": old_rate,
            "new_rate": new_rate,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
